#!/usr/bin/env python3
"""Publish only the reviewed HA captures; preserve other UI review assets."""
from pathlib import Path
from PIL import Image
import argparse,json,re,shutil,hashlib

HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>米家卡片 · LVGL 审核</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f5f7;color:#22262b;font-family:"Segoe UI","Microsoft YaHei",sans-serif}header{padding:24px 28px;background:#fff;border-bottom:1px solid #e6e9ed}h1{margin:0 0 10px;font-size:26px;font-weight:600}p{font-size:13px;line-height:1.8;color:#7c858e;margin:6px 0 12px}a{color:#3486c5;text-decoration:none}header>a{float:right}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #e0e5ea;background:#fff;border-radius:8px;color:#63717e;padding:9px 15px}button.active{background:#eaf4ff;border-color:#b5d7fa;color:#287bd1}.toolbar{display:flex;gap:10px;flex-wrap:wrap;padding:14px 28px;position:sticky;top:0;background:#f4f5f7f5;z-index:3;border-bottom:1px solid #e4e8ed}input,select{border:1px solid #dfe5ea;background:#fff;border-radius:8px;padding:9px 12px}input{width:250px}#count{margin-left:auto;font-size:12px;align-self:center;color:#83909a}main{max-width:1320px;margin:auto;padding:24px 28px 60px}h2{font-size:20px;font-weight:600;margin:0 0 8px}.intro{margin-bottom:34px}.flowtabs{display:flex;gap:8px;margin:14px 0}.stage{position:relative;border:1px solid #e0e4e9;border-radius:14px;overflow:hidden;background:#fff}.stage img{display:block;width:100%}.hotspot{position:absolute;border:0;padding:0;background:transparent;border-radius:0;color:transparent}.hotspot:hover,.hotspot:focus-visible{background:#379bff12;outline:2px solid #379bff80;outline-offset:-2px}.pairs{display:grid;grid-template-columns:1fr 1fr;gap:18px}.frame{background:#fff;border:1px solid #e2e6eb;border-radius:12px;overflow:hidden}.frame>span{display:block;font-size:12px;padding:12px 16px;border-bottom:1px solid #eff1f4;color:#83909a}.frame>img{width:100%;display:block}.group{margin:34px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.item{border:1px solid #e2e6eb;border-radius:14px;overflow:hidden;background:#fff}.item header{padding:14px 16px;background:#fff;border-bottom:1px solid #eff1f4}.item strong{font-size:14px;font-weight:600}.item small{display:block;color:#a0a9b2;font-size:11px;margin-top:4px}.compare{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:18px;background:#fafbfc;align-items:start}.compare figure{margin:0}.compare figcaption{font-size:11px;color:#8a949e;text-align:center;margin:10px 0}.cardview{position:relative}.cardview img,.reference img{display:block;width:100%;border-radius:10px}.reference img{background:#fff}.cardview button{padding:0;position:absolute;bottom:0;left:0;width:100%;border:0;background:transparent;color:transparent;border-radius:0 0 10px 10px}.cardview button:hover,.cardview button:focus-visible{background:#379bff15;outline:2px solid #379bff70;outline-offset:-2px}.openmore{margin:0 18px 16px;font-size:12px}.empty{color:#8c959f;text-align:center;padding:50px}#dialog{position:fixed;inset:0;background:#161c25ed;z-index:9;padding:50px 24px;display:none;align-items:center;justify-content:center}#dialog.open{display:flex}#dialog .stage{max-width:1200px;width:100%;max-height:90vh}#dialog img{max-height:85vh;object-fit:contain}#dismiss{position:absolute;right:24px;top:12px;color:#fff;background:#ffffff12;border-color:#ffffff35}footer{font-size:12px;color:#97a1ab;padding:20px 28px;border-top:1px solid #e2e6eb}@media(max-width:760px){header,.toolbar,main{padding-left:16px;padding-right:16px}.grid,.pairs{grid-template-columns:1fr}#count{margin-left:0}.compare{gap:10px;padding:12px}h1{font-size:22px}header>a{float:none;display:block;margin-bottom:12px}}@media(min-width:1600px){main{max-width:1580px}.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
</style><header><a href="index.html">全部界面 ↗</a><h1>米家卡片 · 组合与展开审核</h1><p>59 个设备品类 · 127 条属性组合 · 25 种参考版式。保留网页快捷卡片，“更多操作”使用统一样式的原有详情页。<br>以下为真实 LVGL 渲染，数值为离线示例；审核页可跳转截图检查流程，未连接设备、未刷机。</p><a href="https://iot.mi.com/v2/new/doc/resources-and-services/design/feature-define/quick-card" target="_blank" rel="noopener">米家快捷卡片规范 ↗</a></header>
<div class="toolbar"><button data-theme="light" class="active">浅色</button><button data-theme="dark">深色</button><input id="search" type="search" placeholder="搜索设备品类"><select id="category"><option value="">全部 59 个品类</option></select><span id="count"></span></div>
<main><section class="intro"><h2>每台设备自选大小 · 首页自动混排</h2><p>进入右上角“布局”，点设备切换小卡 / 大卡，再点“完成”。宽卡占两列，较高的卡片占两行；选择按设备和 HA 服务端保存。点大卡“更多操作”进入详情，返回后保留原组合。</p><div class="flowtabs"><button data-flow="overview">全部小卡</button><button data-flow="mixed" class="active">一张大卡＋小卡</button><button data-flow="two">两台大卡 · 第一页</button><button data-flow="page2">第二页</button><button data-flow="edit">编辑大小</button><button data-flow="quick">点击小卡展开</button><button data-flow="more">更多操作</button></div><div class="stage" id="flowstage"><img id="flowimage" alt="真实 LVGL 家居界面"><button id="flowhotspot" class="hotspot"></button></div></section>
<section class="intro"><h2>入口卡片前后对照</h2><p>温度、湿度与 PM2.5 主读数使用 40 px 原生字体，与图标居中对齐；20 px 单位与数值基线对齐，间距 6 px。设备插画、独立圆形开关和 8 px 进度条沿用当前组合。</p><div class="pairs"><div class="frame"><span>原版</span><img id="before" alt="原版家居总览"></div><div class="frame"><span>修改后 · 真实 LVGL</span><img id="after" alt="修改后的家居总览"></div></div></section>
<div id="catalog"></div></main><footer>参考图中的占位文字已替换为设备名称和示例数据。点击每张卡片底部“更多操作”可检查详情页。接口未支持的控制仍为只读。<a href="mijia-catalog.json">品类与属性清单 ↗</a></footer>
<div id="dialog" role="dialog" aria-modal="true" aria-label="更多操作详情"><button id="dismiss">关闭 ×</button><div class="stage"><img id="moreimage" alt="真实 LVGL 更多操作页"><button id="return" class="hotspot" aria-label="返回快捷卡片" style="left:17.18%;top:13.33%;width:3.13%;height:5%"></button></div></div>
<script>
const DATA=__DATA__, $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const requestedFlow=new URLSearchParams(location.search).get('flow');let theme='light',flow=['overview','mixed','two','page2','edit','quick','more'].includes(requestedFlow)?requestedFlow:'mixed',currentMore=null,returnFlow='mixed';
const names=new Map(DATA.map(r=>[r.type,r.name]));names.forEach((name,type)=>{const o=document.createElement('option');o.value=type;o.textContent=name+' / '+type;$('#category').append(o)});
function renderFlow(){const file={overview:'hass-overview',mixed:'hass-mixed',two:'hass-mixed-two',page2:'hass-mixed-two-page2',edit:'hass-layout-editor',quick:'hass-device-detail',more:returnFlow==='quick'?'hass-device-more':'hass-mixed-more'}[flow];$('#flowimage').src=theme+'-'+file+'.png';document.querySelectorAll('[data-flow]').forEach(b=>b.classList.toggle('active',b.dataset.flow===flow));const b=$('#flowhotspot');b.style.cssText=flow==='overview'?'left:17.58%;top:23.33%;width:26%;height:31.67%':flow==='quick'?'left:55.47%;top:61.83%;width:42.97%;height:10%':flow==='more'?'left:17.18%;top:13.33%;width:3.13%;height:5%':flow==='edit'?'left:85.55%;top:13.33%;width:5.47%;height:5%':flow==='two'?'left:94.14%;top:94.5%;width:3.52%;height:5%':flow==='page2'?'left:90.23%;top:94.5%;width:3.52%;height:5%':'left:17.58%;top:48.67%;width:53.32%;height:6.5%';b.setAttribute('aria-label',flow==='overview'?'展开书桌台灯':flow==='more'?'返回原组合':flow==='edit'?'完成布局':flow==='two'?'下一页':flow==='page2'?'上一页':'打开更多操作');$('#before').src='before-mijia-'+theme+'-hass-overview.png';$('#after').src=theme+'-hass-mixed.png';}
function render(){renderFlow();const query=$('#search').value.trim().toLowerCase(),category=$('#category').value,rows=DATA.filter(r=>(!category||r.type===category)&&(!query||(r.name+' '+r.type).toLowerCase().includes(query)));$('#count').textContent=new Set(rows.map(r=>r.type)).size+' 个品类 · '+rows.length+' 种组合';let html='';names.forEach((name,type)=>{const group=rows.filter(r=>r.type===type);if(!group.length)return;html+='<section class="group"><h2>'+esc(name)+'</h2><p>'+esc(type)+' · '+group.length+' 种属性组合</p><div class="grid">';group.forEach(r=>{html+='<article class="item"><header><strong>'+esc(r.name)+' · 组合 '+r.variant+'</strong><small>参考版式 '+String(r.layout).padStart(2,'0')+'</small></header><div class="compare"><figure class="reference"><a href="'+r.reference_file+'" target="_blank"><img loading="lazy" src="'+r.reference_file+'" alt="网页参考 '+esc(r.name)+'"></a><figcaption>网页参考</figcaption></figure><figure><div class="cardview"><a href="'+theme+'-hass-quick-'+r.key+'.png" target="_blank"><img loading="lazy" src="mijia-card-'+theme+'-'+r.key+'.png" alt="LVGL '+esc(r.name)+'"></a><button data-more="'+r.key+'" style="height:'+r.footer_percent+'%" aria-label="'+esc(r.name)+' 更多操作">更多操作</button></div><figcaption>LVGL · 实際数据布局</figcaption></figure></div><button class="openmore" data-more="'+r.key+'">更多操作 ↗</button></article>';});html+='</div></section>';});$('#catalog').innerHTML=html||'<div class="empty">没有匹配的品类</div>';}
function showMore(key){currentMore=key;$('#moreimage').src=theme+'-hass-quick-'+key+'-more.png';$('#dialog').classList.add('open');$('#dismiss').focus()}
function closeMore(){$('#dialog').classList.remove('open');currentMore=null}
$('#catalog').onclick=e=>{const b=e.target.closest('[data-more]');if(b)showMore(b.dataset.more)};$('#dismiss').onclick=closeMore;$('#return').onclick=closeMore;$('#dialog').onclick=e=>{if(e.target===$('#dialog'))closeMore()};document.onkeydown=e=>{if(e.key==='Escape')closeMore()};$('#search').oninput=render;$('#category').onchange=render;$('#flowhotspot').onclick=()=>{if(flow==='overview')flow='quick';else if(flow==='more')flow=returnFlow;else if(flow==='edit')flow='mixed';else if(flow==='two')flow='page2';else if(flow==='page2')flow='two';else{returnFlow=flow;flow='more';}renderFlow()};document.querySelectorAll('[data-flow]').forEach(b=>b.onclick=()=>{if(b.dataset.flow==='more')returnFlow=flow==='quick'?'quick':'mixed';flow=b.dataset.flow;renderFlow()});document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{theme=b.dataset.theme;document.querySelectorAll('[data-theme]').forEach(x=>x.classList.toggle('active',x===b));render();if(currentMore)showMore(currentMore)});render();
</script></html>'''

def main():
    p=argparse.ArgumentParser();p.add_argument('--native',type=Path,required=True);a=p.parse_args()
    repo=Path(__file__).resolve().parents[1];root=repo.parent;out=root/'output/all-ui-review';refs=root/'output/refined-ui'
    catalog=json.loads((repo/'app/homeassistant/quick-card-catalog.json').read_text(encoding='utf-8'));specs=catalog['variants']
    fresh=[r for r in json.loads((a.native/'screens.json').read_text(encoding='utf-8')) if r['id'].startswith('hass')]
    assert len(fresh)==(14+254)*2,len(fresh)
    for row in fresh:
        shutil.copy2(a.native/row['file'],out/row['file'])
        m=re.match(r'hass-quick-(\d+)(-more)?$',row['id'])
        if m:
            spec=specs[int(m[1])-1];row['title']=spec['name']+' · '+('更多操作' if m[2] else '网页快捷卡片')+' · 组合 '+str(spec['variant'])
    old=json.loads((out/'screens.json').read_text(encoding='utf-8'));merged=[];inserted=set()
    for row in old:
        if row['id'].startswith('hass'):
            if row['theme'] not in inserted:merged.extend(r for r in fresh if r['theme']==row['theme']);inserted.add(row['theme'])
        else:merged.append(row)
    for theme in ['浅色','深色']:
        if theme not in inserted:merged.extend(r for r in fresh if r['theme']==theme)
    (out/'screens.json').write_text(json.dumps(merged,ensure_ascii=False,indent=2),encoding='utf-8')
    for file in (refs/'mijia-before').glob('*.png'):shutil.copy2(file,out/('before-mijia-'+file.name))
    rows=[]
    for i,spec in enumerate(specs,1):
        key=f'{i:03d}';shutil.copy2(refs/spec['file'],out/spec['file']);cw=440;ch=round(cw*spec['size'][1]/spec['size'][0])
        if ch>394:ch=394;cw=round(ch*spec['size'][0]/spec['size'][1])
        for theme in ['light','dark']:
            with Image.open(out/f'{theme}-hass-quick-{key}.png') as image:image.crop((1024-16-cw,140,1008,140+ch)).save(out/f'mijia-card-{theme}-{key}.png')
        rows.append(dict(spec,key=key,reference_file=spec['file'],footer_percent=round(72*cw/524/ch*100,2)))
    (out/'mijia-catalog.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
    (out/'mijia.html').write_text(HTML.replace('__DATA__',json.dumps(rows,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
    records=json.loads((a.native/'render-sources.json').read_text(encoding='utf-8'))
    for path in [repo/'app/espdl-quickapp/overlay/apps/system/desktop/homeassistant/app.js',repo/'app/homeassistant/quick-card-catalog.json',repo/'app/espdl-quickapp/tests/mijia_card_fixture.js',repo/'app/espdl-quickapp/tests/mijia_card_fixture.h']:
        records.append({'source':str(path.relative_to(repo)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
    (out/'mijia-render-sources.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf-8')
    print('MIJIA_REVIEW_OK',len(catalog['types']),len(rows),len(fresh),'native HA screenshots')
if __name__=='__main__':main()
